    # interior fill: cells strictly inside bbox not on marker, but bg -> keep? Instead: fill holes completely enclosed by markers/border? 
    # new idea: fill entire interior region reachable without crossing markers? Try flood from outside bbox.
    from collections import deque
    H,W=len(inp),len(inp[0])
    outo=[r_[:] for r_ in inp]
    q=deque()
    for i in range(H):
        for j in (0,W-1):
            if inp[i][j]==bg: q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if inp[i][j]==bg: q.append((i,j))
    seen=set()
    while q:
        i,j=q.popleft()
        if (i,j) in seen: continue
        seen.add((i,j))
        if inp[i][j]==bg and not (r0<=i<=r1 and c0<=j<=c1): continue
        # allow movement through bg anywhere outside
        if inp[i][j]!=bg: continue
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and (ni,nj) not in seen and inp[ni][nj]==bg and not (r0<=ni<=r1 and c0<=nj<=c1):
                q.append((ni,nj))
    for i in range(H):
        for j in range(W):
            if inp[i][j]==bg and (i,j) not in seen: outo[i][j]=fill
    return outo
